var e=e=>e.normalize(`NFD`).replace(/[\u0300-\u036f]/g,``).toLowerCase(),t=`Retirado das opções clínicas por solicitação do usuário: validação ainda pendente.`,n=new Set([`procainamida-taquicardia`,`cetamina-iot`,`cetamina-infusao`,`succinilcolina-iot`,`lorazepam-crise`,`fosfenitoina`,`valproato`]);function r(t){return/\b(acetato de calcio|fosfenitoina|procainamida|cetamina|ketamina|succinilcolina|suxametonio)\b/.test(e(t))}function i(t,n=``,i=``){let a=e(t),o=e(n+` `+i);return!!(r(t)||/\bondansetrona\b/.test(a)&&/radioterap/.test(o)||/\bverapamil\b/.test(a)&&/hipertens|angina|isquemi/.test(o)||/\bclopidogrel\b/.test(a)&&/stent|dispositivo|flow.divert/.test(e(n))||/\blorazepam\b/.test(a)&&/\b(iv|ev|im)\b|intraven|injet|catatonia|crise|status/.test(o)||/valpro|divalpro/.test(a)&&/\b(iv|ev)\b|intraven|injet|status epilept/.test(o)||/\bcetirizina\b/.test(a)&&/solu[cç]|xarope|gota/.test(o))}var a=new Set([`pdf-015-row-02`,`pdf-108-row-01`,`pdf-108-row-02`,`pdf-282-row-03`,`pdf-332-row-04`,`pdf-442-row-03-hta`,`pdf-442-row-03-angina`,`pdf-496-row-01`,`pdf-496-row-02`]);function o(e,t){return![`omitted`,`unresolved`].includes(t.status)&&!a.has(t.id)&&!i(e,t.indication,t.dose_text)}var s=[[`IV/IO em bolus, seguido de flush. Dose: 0,01 mg/kg; máximo 1 mg.`,`0,01 mg/kg IV/IO em bolus + flush; máx. 1 mg.`],[`Não administrar o volume calculado como se a ampola fosse 1 mg/mL: isso produz erro de 10 vezes.`,`Ampola 1 mg/mL: não usar este volume (erro de 10×).`],[`Se houver apenas 1 mg/mL: aspirar 1 mL e completar para 10 mL com SF 0,9% → 0,1 mg/mL. Rotular imediatamente.`,`Estoque 1 mg/mL: 1 mL + SF 0,9% até 10 mL FINAIS → 0,1 mg/mL. Rotular imediatamente.`],[`5 mg/kg IV/IO. Máximo 300 mg na primeira dose; pode repetir até 3 doses totais, com máximo 150 mg nas subsequentes.`,`5 mg/kg IV/IO. 1ª: máx. 300 mg; subsequentes: máx. 150 mg. Até 3 doses totais.`],[`Dose emergencial pediátrica protocolar AHA; concentração de PCR do CHEO Emergency, com SG 5%. A bula Fresenius Kabi consultada contraindica uso em crianças e contém álcool benzílico; esta referência pediátrica PALS/CHEO não valida esse fabricante. A exceção de ressuscitação da bula não é tratada como autorização pediátrica automática; conciliar produto/excipientes pela equipe responsável. Não administrar a ampola pura por este plano. O modo de administração muda completamente quando há pulso: bolus rápido pode causar hipotensão e bradicardia.`,`PCR: dose AHA, concentração CHEO em SG 5%. Fresenius Kabi: contraindicado em crianças; contém álcool benzílico. PALS/CHEO e exceção de ressuscitação da bula não validam uso pediátrico desse produto; equipe deve conciliar fabricante/excipientes. Não usar ampola pura. Com pulso: outro regime; bolus rápido pode causar hipotensão/bradicardia.`],[`Preparo proporcional à dose de cada etapa: aspirar dose/50 mL do estoque 50 mg/mL e acrescentar SG 5% até dose/1 mL finais a 1 mg/mL, conforme CHEO Emergency para PCR. Não usar receita fixa de 50 mg quando a dose for maior. Conferir quantidade disponível, volume total e carga hídrica; não administrar ampola pura.`,`Cada etapa: dose/50 mL do estoque 50 mg/mL + SG 5% até dose/1 mL FINAL → 1 mg/mL (CHEO PCR). Dose >50 mg: não usar receita fixa de 50 mg. Conferir quantidade, volume/carga hídrica; não usar puro.`],[`Usar o volume calculado da apresentação selecionada quando mensurável. A diluição opcional a 5 mg/mL não está validada neste ramo pelas fontes atuais; não usar o volume dessa diluição. Para volumes pequenos, exige diluição proporcional padronizada e rotulada pelo serviço antes de recalcular.`,`Aspirar volume mensurável da apresentação selecionada. Diluição a 5 mg/mL não validada neste ramo: não usar. Volume pequeno: padronizar/rotular diluição proporcional no serviço e recalcular.`],[`0,02 mg/kg IV/IO; mínimo 0,1 mg, máximo 0,5 mg. Pode repetir uma vez.`,`0,02 mg/kg IV/IO; mín. 0,1 mg, máx. 0,5 mg. Repetir até uma vez.`],[`Pode ser ineficaz no coração transplantado ou bloqueio AV avançado com QRS largo; não atrasar tratamento definitivo. O teto de 0,5 mg segue AHA pediátrica, não o teto maior da bula para adolescentes. A dose mínima de 0,1 mg vale para tratamento da bradicardia; não deve ser aplicada à atropina pré-IOT.`,`Pode falhar no transplantado/bloqueio AV avançado com QRS largo; não atrasar tratamento definitivo. Teto AHA 0,5 mg (não teto adolescente da bula); mínimo 0,1 mg só na bradicardia, não pré-IOT.`],[`Não há diluição obrigatória; conferir a ampola. Se usar outra concentração, o volume exibido deixa de ser válido.`,`Diluição não obrigatória; conferir ampola. Outra concentração exige recalcular volume.`],[`1ª dose 0,1 mg/kg (máx. 6 mg); 2ª dose 0,2 mg/kg (máx. 12 mg), em push ultrarrápido.`,`Push ultrarrápido: 1ª 0,1 mg/kg (máx. 6 mg); 2ª 0,2 mg/kg (máx. 12 mg).`],[`Contraindicada em doença broncoespástica/asma, bloqueio AV de segundo ou terceiro grau e disfunção do nó sinusal, salvo marca-passo funcionante nos bloqueios/disfunção sinusal. Não usar em taquicardia irregular ou polimórfica. Registrar ECG contínuo durante a administração.`,`Contraindicada: broncoespasmo/asma, bloqueio AV de segundo/terceiro grau ou disfunção sinusal (exceção: marca-passo funcionante para bloqueio/disfunção sinusal). Não usar na taquicardia irregular/polimórfica. ECG contínuo.`],[`Não diluir. Preparar em seringa separada e usar torneira próxima ao acesso, com flush imediato.`,`Sem diluir; seringa separada, torneira junto ao acesso e flush imediato.`],[`Alíquota de 10–20 mL/kg, com reavaliação de perfusão e sinais de sobrecarga após cada alíquota.`,`10–20 mL/kg/alíquota; reavaliar perfusão/sobrecarga após cada uma.`],[`Não programar múltiplos bolus sem reavaliação. Reduzir/cessar se surgirem estertores, hepatomegalia ou piora respiratória.`,`Não repetir bolus sem reavaliar. Estertores, hepatomegalia ou piora respiratória: reduzir/cessar.`],[`0,02 mg/kg IV. Não aplicar dose mínima de 0,1 mg nesta indicação.`,`0,02 mg/kg IV; sem mínimo de 0,1 mg neste ramo.`],[`Não usar apenas porque a criança é pequena. Corrigir hipóxia, preparar ventilação e antecipar deterioração hemodinâmica.`,`Não indicar só por tamanho. Corrigir hipóxia, preparar ventilação e antecipar deterioração hemodinâmica.`],[`Se o volume for impreciso, preparar diluição padronizada e rotulada pela farmácia/serviço.`,`Volume impreciso: diluição padronizada/rotulada pela farmácia/serviço.`],[`1–2 mcg/kg IV, em 3–5 min; máximo 2 mcg/kg por administração IV direta neste ramo CHEO.`,`1–2 mcg/kg IV em 3–5 min; máx. CHEO 2 mcg/kg/administração IV direta.`],[`Push rápido ou dose alta pode causar rigidez de parede torácica, apneia, bradicardia e hipotensão.`,`Push rápido/dose alta: rigidez torácica, apneia, bradicardia e hipotensão.`],[`Preparo proporcional à alternativa de dose: aspirar dose/50 mL de fentanila 50 mcg/mL e acrescentar SF 0,9% até dose/10 mL finais a 10 mcg/mL. Preparar quantidade suficiente para a dose escolhida; não somar alternativas nem retirar mais que o preparado.`,`Por alternativa: dose/50 mL de 50 mcg/mL + SF 0,9% até dose/10 mL FINAL → 10 mcg/mL. Preparar toda a dose; não somar alternativas nem aspirar além do preparado.`],[`0,3 mg/kg IV lentamente; não exceder 10 mL/min do produto 2 mg/mL. Não misturar com outros medicamentos.`,`0,3 mg/kg IV lento; 2 mg/mL: ≤10 mL/min. Não misturar medicamentos.`],[`Mioclonias e supressão adrenal. Evitar em sepse/choque séptico. Em recém-nascidos e menores de 6 meses, evitar salvo indicação urgente; uso off-label nessa faixa segundo AEP. Considerar excipientes e reduzir na cirrose. Não administrar em infusão contínua ou doses repetidas.`,`Mioclonias/supressão adrenal; evitar na sepse/choque séptico. RN/<6 meses: evitar salvo urgência (off-label AEP). Avaliar excipientes; reduzir na cirrose. Sem infusão contínua/repetição.`],[`Seleção inicial reduzida de 1–2 mg/kg IV, titulada em 30–60 s. PCH descreve 1–3 mg/kg para indução; 2 mg/kg não é máximo universal. Reduzir conforme estado clínico.`,`Início reduzido: 1–2 mg/kg IV em 30–60 s; titular/reduzir conforme clínica. PCH: 1–3 mg/kg na indução; 2 mg/kg não é teto universal.`],[`Hipotensão e depressão respiratória. Não usar a recomendação do Excel de iniciar lactente com 3 mg/kg; infusão prolongada em TCE pediátrico grave não é recomendada.`,`Hipotensão/depressão respiratória. Não iniciar lactente com 3 mg/kg conforme Excel antigo. Infusão prolongada não recomendada no TCE pediátrico grave.`],[`Não diluir; técnica asséptica rigorosa e descarte conforme fabricante.`,`Sem diluir; assepsia rigorosa e descarte conforme fabricante.`],[`Paralisia não seda nem trata dor. Planejar sedoanalgesia pós-IOT antes de administrar. RSI pediátrica pode ser off-label na bula do fabricante.`,`Paralisia não seda nem alivia dor. Planejar sedoanalgesia pós-IOT antes do uso. RSI pediátrica pode ser off-label conforme fabricante.`],[`Bolus: não diluir. Para infusão contínua, usar preparação separada a 2 mg/mL; nunca calcular essa infusão como 10 mg/mL.`,`Bolus: sem diluir. Infusão: preparo separado a 2 mg/mL; nunca calcular como 10 mg/mL.`],[`0,05–1 mcg/kg/min, titular à perfusão e pressão-alvo. Preferir acesso central; pode iniciar perifericamente com vigilância estrita enquanto se obtém acesso definitivo.`,`0,05–1 mcg/kg/min; titular por perfusão/pressão-alvo. Preferir central; início periférico com vigilância estrita até acesso definitivo.`],[`Concentrações institucionais variam. Se a bolsa não for 40 mcg/mL, descarte as vazões exibidas e recalcule.`,`Bolsa diferente de 40 mcg/mL: descartar vazões exibidas e recalcular.`],[`Produto Hypofarma:4mL(4mg de base)+96mL de SG5%=100mL finais,40mcg/mL. Proteger da luz. Bula não recomenda SF isolado; confirmar base/sal. Uso pediátrico off-label em relação à bula adulta, sustentado pela diretriz pediátrica.`,`Hypofarma: 4mL (4mg base) + 96mL SG5% = 100mL FINAIS, 40mcg/mL. Fotoproteção; SF isolado não recomendado. Conferir base/sal. Pediatria: off-label perante bula adulta, respaldado por diretriz pediátrica.`],[`0,05–1 mcg/kg/min, titular. Iniciar na faixa baixa e reavaliar lactato, perfusão, glicemia, ritmo e pressão. Acima de 0,5 mcg/kg/min, somente com UTI (QPEC Sepsis CHQ-GDL-60010).`,`0,05–1 mcg/kg/min; iniciar na faixa baixa e titular. Reavaliar lactato, perfusão, glicemia, ritmo e pressão. Acima de 0,5 mcg/kg/min, somente com UTI (QPEC Sepsis).`],[`Não confundir com a solução de PCR 0,1 mg/mL: a bolsa da infusão deste exemplo é 10 vezes menos concentrada.`,`PCR: 0,1 mg/mL; bolsa deste exemplo 10× menos concentrada. Não confundir.`],[`Adicionar 1 mg e completar para 100 mL com SF 0,9% ou SG 5% → 10 mcg/mL.`,`1 mg + SF 0,9% ou SG 5% até 100 mL FINAIS → 10 mcg/mL.`],[`2,5–20 mcg/kg/min nesta seleção, titulada. CHEO descreve faixa usual 2,5–15 e máximo 40 mcg/kg/min; 20 não é teto absoluto. Acima de 5 mcg/kg/min, preferir acesso central.`,`Seleção: 2,5–20 mcg/kg/min, titulada. CHEO: usual 2,5–15; máx. 40 mcg/kg/min (20 não é teto). >5 mcg/kg/min: preferir central.`],[`Pode piorar hipotensão e causar taquiarritmia. Em choque vasoplégico, frequentemente exige vasopressor associado. ALERTA ANVISA (11/09/2026): não utilizar os lotes Hypofarma 24092127, 24102310, 25102244, 25102243 e 25112308; recolhimento e proibição por alterações visuais/partículas. Fonte: https://www.gov.br/anvisa/pt-br/assuntos/noticias-anvisa/2026/anvisa-proibe-produto-da-medicina-chinesa-vendido-de-forma-irregular`,`Risco de hipotensão/taquiarritmia; vasoplegia frequentemente exige vasopressor. ANVISA (11/09/2026): NÃO USAR Hypofarma lotes 24092127, 24102310, 25102244, 25102243, 25112308; recolhidos/proibidos por alterações visuais/partículas. Fonte: https://www.gov.br/anvisa/pt-br/assuntos/noticias-anvisa/2026/anvisa-proibe-produto-da-medicina-chinesa-vendido-de-forma-irregular`],[`Adicionar 250 mg e completar para 100 mL → 2,5 mg/mL. Proteger e checar compatibilidade conforme protocolo.`,`250 mg até 100 mL FINAIS → 2,5 mg/mL. Proteção/compatibilidade conforme protocolo.`],[`0,25–0,75 mcg/kg/min. Omitir bolus na instabilidade hemodinâmica.`,`0,25–0,75 mcg/kg/min; omitir bolus se instável.`],[`Hipotensão e arritmia. A bula Fresenius não recomenda uso pediátrico na insuficiência renal; não aplicar automaticamente a tabela adulta. Não misturar com furosemida, bumetanida ou bicarbonato. O regime pediátrico da bula é de até 35 h. Não usar vazão desta folha se a bolsa tiver 100 mcg/mL.`,`Hipotensão/arritmia. Fresenius: pediatria até 35 h; não recomendada na insuficiência renal, sem ajuste adulto automático. Incompatível com furosemida, bumetanida e bicarbonato. Bolsa 100 mcg/mL: recalcular vazão.`],[`Adicionar 20 mg e completar para 100 mL → 200 mcg/mL. Adequar ao padrão institucional.`,`20 mg até 100 mL FINAIS → 200 mcg/mL; adequar ao padrão local.`],[`3.200 mcg/mL exige acesso venoso central. Monitorar ECG, pressão e perfusão; vigiar extravasamento e taquiarritmia. Não reutilizar esta vazão para bolsas de 800 ou 1.600 mcg/mL.`,`3.200 mcg/mL: CENTRAL. Monitorar ECG, pressão, perfusão, extravasamento/taquiarritmia. Bolsas 800 ou 1.600 mcg/mL: recalcular vazões.`],[`Adicionar 160 mg e completar para 50 mL: 3,2 mg/mL. Administrar por acesso venoso central. CHEO também descreve 800 e 1.600 mcg/mL, que geram vazões diferentes.`,`160 mg até 50 mL FINAIS → 3,2 mg/mL; CENTRAL. CHEO 800/1.600 mcg/mL: outras vazões.`],[`0,5–5 mcg/kg/h, titulada à resposta e ao contexto clínico.`,`0,5–5 mcg/kg/h; titular à resposta/contexto.`],[`A unidade é mcg/kg/HORA. O Excel misturava minuto e hora, com potencial erro de 60×. Vigiar apneia, rigidez, íleo e tolerância.`,`mcg/kg/HORA: confusão minuto/hora no Excel causava erro de 60×. Vigiar apneia, rigidez, íleo e tolerância.`],[`Adicionar 500 mcg e completar para 100 mL com SF 0,9% → 5 mcg/mL. Para seringa menor, manter a mesma razão e rotular.`,`500 mcg + SF 0,9% até 100 mL FINAIS → 5 mcg/mL. Seringa menor: mesma proporção; rotular.`],[`Maiores de 1 mês, analgesia em ambiente crítico: iniciar 0,02 mg/kg/h; faixa usual 0,01–0,04 mg/kg/h. Titular em 0,01 mg/kg/h a cada 2–4 h conforme resposta. Doses maiores pertencem a contextos selecionados, não são o ponto inicial padrão.`,`>1 mês, analgesia em área crítica: início 0,02 mg/kg/h; usual 0,01–0,04 mg/kg/h. Titular +0,01 mg/kg/h a cada 2–4 h por resposta. Doses maiores: contextos específicos, não início padrão.`],[`Uso pediátrico off-label perante Dimorf injetável, de bula adulta. Doses e concentrações nominais de sulfato de morfina, sem conversão para base. Reduzir e individualizar em disfunção renal/hepática ou instabilidade; vigiar ventilação, nível de consciência e pressão. Faixa usual não equivale a máximo absoluto universal.`,`Pediatria off-label (Dimorf adulto); dose/concentração em sulfato, não base. Disfunção renal/hepática ou instabilidade: reduzir/individualizar. Vigiar ventilação, consciência e pressão; faixa usual não é teto universal.`],[`Adicionar 100 mg e completar para 100 mL com SF 0,9% → 1 mg/mL. Utilizar preparação padronizada do serviço.`,`100 mg + SF 0,9% até 100 mL FINAIS → 1 mg/mL; preparo padronizado local.`],[`0,03–0,2 mg/kg/h, titulada à meta. Reavaliar diariamente a menor dose efetiva.`,`0,03–0,2 mg/kg/h; titular à meta e reavaliar menor dose efetiva diariamente.`],[`Hipotensão, delirium, tolerância e abstinência. Faixas de até 2 mg/kg/h pertencem ao estado de mal refratário, não à sedação comum.`,`Hipotensão, delirium, tolerância/abstinência. Até 2 mg/kg/h: só estado de mal refratário, não sedação comum.`],[`Adicionar 100 mg e completar para 100 mL com SF 0,9% → 1 mg/mL. Confirmar estabilidade e padrão institucional.`,`100 mg + SF 0,9% até 100 mL FINAIS → 1 mg/mL; conferir estabilidade/padrão local.`],[`Após o período neonatal: 0,2–2 mcg/kg/h no ramo CHEO; iniciar na faixa baixa e titular à meta. Evitar ataque de rotina.`,`Pós-neonatal, CHEO: 0,2–2 mcg/kg/h; início na faixa baixa, titular à meta. Sem ataque rotineiro.`],[`Uso pediátrico off-label perante Precedex BR. Individualizar na disfunção hepática. Bradicardia e hipotensão, sobretudo com bolus ou hipovolemia. O bolus rápido descrito no Excel foi removido.`,`Pediatria off-label (Precedex BR); individualizar se disfunção hepática. Bradicardia/hipotensão, sobretudo bolus/hipovolemia. Bolus rápido do Excel excluído.`],[`Adicionar 400 mcg e completar para 100 mL com SF 0,9% → 4 mcg/mL.`,`400 mcg + SF 0,9% até 100 mL FINAIS → 4 mcg/mL.`],[`0,3–0,6 mg/kg/h, titulada ao menor bloqueio necessário, com train-of-four quando disponível.`,`0,3–0,6 mg/kg/h; menor bloqueio necessário, com train-of-four disponível.`],[`Nunca iniciar sem sedoanalgesia adequada. Infusão pediátrica em UTI é off-label perante Rocuron BR. Monitorar bloqueio com train-of-four; disfunção renal/hepática pode prolongar o efeito.`,`Sedoanalgesia prévia obrigatória. UTI pediátrica off-label (Rocuron BR). Monitorar train-of-four; disfunção renal/hepática pode prolongar efeito.`],[`Aspirar 10 mL de rocurônio 10 mg/mL (100 mg) e acrescentar 40 mL de SG 5%: 50 mL finais a 2 mg/mL, conforme CIDD Queensland. Não reutilizar vazões de 1 ou 10 mg/mL.`,`10 mL de 10 mg/mL (100 mg) + 40 mL SG 5% = 50 mL FINAIS, 2 mg/mL (CIDD Queensland). Não reutilizar vazões de 1 ou 10 mg/mL.`],[`Iniciar 0,1 mg/kg/h; titular até 2 mg/kg/h, titulada ao controle eletrográfico por equipe especializada.`,`Início 0,1 mg/kg/h; titular até 2 mg/kg/h por controle eletrográfico/equipe especializada.`],[`Dose alta exige via aérea, suporte vasoativo e EEG contínuo. Não transportar esta faixa para sedação pós-IOT rotineira.`,`Dose alta: via aérea, suporte vasoativo e EEG contínuo. Não aplicar à sedação pós-IOT rotineira.`],[`Adicionar 100 mg e completar para 100 mL → 1 mg/mL. Concentração institucional pode ser maior para restrição de volume.`,`100 mg até 100 mL FINAIS → 1 mg/mL. Restrição hídrica: concentração local pode ser maior.`],[`IV 0,15 mg/kg (máx. 10 mg); IN ou IM 0,2 mg/kg (máx. 10 mg), conforme calculadora de emergência CHEO. Reavaliar respiração e glicemia imediatamente.`,`CHEO: IV 0,15 mg/kg; IN/IM 0,2 mg/kg (máx. 10 mg por via). Reavaliar imediatamente respiração/glicemia.`],[`Depressão respiratória é previsível, mas subtratar estado de mal também é perigoso. Preparar ventilação; limitar benzodiazepínicos antes da segunda linha.`,`Preparar ventilação: risco de depressão respiratória. Evitar subtratamento; limitar benzodiazepínicos antes da segunda linha.`],[`IV: pode diluir para medida precisa. IN é uso off-label: usar 5 mg/mL, dividir o volume entre as narinas e confirmar protocolo/dispositivo do serviço.`,`IV: diluir se necessário para precisão. IN off-label: 5 mg/mL, dividir entre narinas; confirmar protocolo/dispositivo.`],[`60 mg/kg IV; máximo 4.500 mg, usualmente em 10–15 min conforme protocolo.`,`60 mg/kg IV, máx. 4.500 mg; usual 10–15 min conforme protocolo.`],[`Ajuste renal é relevante para manutenção, mas não deve atrasar a carga tempo-crítica; vigiar agitação e sonolência.`,`Ajuste renal na manutenção não deve atrasar carga. Vigiar agitação/sonolência.`],[`Antara IV 100 mg/mL: completar em SF 0,9% para 15 mg/mL e infundir em 15 min. Limite de concentração da bula brasileira para volume pediátrico reduzido; não transpor CHEO 20/40 mg/mL. Ataque para estado de mal e uso <6 anos são protocolares/off-label.`,`Antara 100 mg/mL + SF 0,9% → 15 mg/mL em 15 min (limite BR para volume reduzido). Não aplicar CHEO 20/40 mg/mL. Ataque no estado de mal/<6 anos: protocolar/off-label.`],[`CHEO: 20 mg/kg IV; máximo 1.000 mg se <50 kg, 1.500 mg se ≥50 kg. Regime protocolar diferente da dose de ataque 10–15 mg/kg da bula Fenital. Respeitar simultaneamente ≤1 mg/kg/min e ≤50 mg/min, com ECG e pressão contínuos.`,`CHEO: 20 mg/kg IV; máx. 1.000 mg (<50 kg) ou 1.500 mg (≥50 kg). Difere da bula Fenital: ataque 10–15 mg/kg. ≤1 mg/kg/min E ≤50 mg/min; ECG/pressão contínuos.`],[`Extravasamento pode causar lesão grave. Não usar em determinadas intoxicações por bloqueadores de canal de sódio sem especialista.`,`Extravasamento: lesão grave. Intoxicação por bloqueadores de sódio: uso somente com especialista.`],[`Diluir somente em SF 0,9%; usar filtro e administrar logo após preparo. Incompatível com soluções glicosadas.`,`Só SF 0,9%, filtro e uso imediato; incompatível com glicosados.`],[`Ataque 20 mg/kg de fenobarbital sódico IV, máximo 1.000 mg neste ramo. Administrar em pelo menos 20 min, sem exceder 1 mg/kg/min nem 30 mg/min. Tempo mínimo = maior valor entre 20 min, dose/peso e dose/30.`,`Ataque IV 20 mg/kg de fenobarbital sódico; máx. 1.000 mg. ≥20 min, ≤1 mg/kg/min E ≤30 mg/min. Tempo mínimo = maior entre 20 min, dose/peso e dose/30.`],[`Dose calculada em mg de fenobarbital sódico: aspirar D/100 mL e completar para D/5 mL com SF 0,9% ou SG 5%, resultando em 5 mg de sal/mL. Confirmar compatibilidade do produto. 20 mg de sal equivalem a 18,27 mg de base, não a 20 mg de base.`,`Dose D em mg de sal: D/100 mL + SF 0,9% ou SG 5% até D/5 mL FINAIS → 5 mg de sal/mL. Conferir compatibilidade. 20 mg de sal = 18,27 mg de base ≠ 20 mg de base.`],[`2–5 mL/kg IV em 10–20 min. Infusão contínua 0,1–1 mL/kg/h apenas em UTI, titulada ao ICP/sódio.`,`Bolus IV 2–5 mL/kg em 10–20 min. Contínua: 0,1–1 mL/kg/h só em UTI; titular por ICP/sódio.`],[`Vigiar sódio, cloro, osmolaridade, acesso e velocidade de correção. Não tratar empiricamente toda alteração neurológica como HIC.`,`Vigiar sódio, cloro, osmolaridade, acesso/correção. Não presumir HIC em toda alteração neurológica.`],[`Não diluir quando solução final já é 3%. Preferir preparação padronizada; checar sódio e osmolaridade.`,`Solução final 3%: sem diluir. Preferir preparo padronizado; conferir sódio/osmolaridade.`],[`0,25–0,5 g/kg IV em 20–30 min, em consulta com neurocirurgia; o plano usa 30 min.`,`0,25–0,5 g/kg IV em 20–30 min, com neurocirurgia; cálculo em 30 min.`],[`Não diluir rotineiramente; inspecionar cristais e usar filtro conforme fabricante.`,`Sem diluição rotineira; inspecionar cristais/filtro conforme fabricante.`],[`0,01 mg/kg IM; máximo 0,5 mg. Repetir a cada 5 min se necessário, com reavaliação contínua.`,`0,01 mg/kg IM, máx. 0,5 mg; repetir a cada 5 min se necessário. Reavaliar continuamente.`],[`A concentração é 10 vezes maior que a solução IV da PCR. Anti-histamínico e corticoide nunca substituem adrenalina IM.`,`Concentração 10× a da PCR IV. Anti-histamínico/corticoide não substituem adrenalina IM.`],[`Não diluir. Aspirar diretamente da ampola 1 mg/mL com seringa apropriada.`,`Ampola 1 mg/mL, sem diluir; seringa apropriada.`],[`CPS: 5 jatos se <20 kg; 10 jatos se ≥20 kg. Repetir a cada 20 min nas primeiras 3 doses conforme gravidade e protocolo.`,`CPS: <20 kg, 5 jatos; ≥20 kg, 10 jatos. A cada 20 min nas primeiras 3 doses, por gravidade/protocolo.`],[`Reavaliar trabalho respiratório, entrada de ar, fala, consciência e saturação — sibilância reduzida pode significar pior fluxo, não melhora.`,`Reavaliar esforço respiratório, entrada de ar, fala, consciência/saturação. Menos sibilância pode ser pior fluxo.`],[`Não se aplica. Administrar um jato por vez no espaçador, com técnica correta.`,`Sem diluição; um jato/vez no espaçador, com técnica correta.`],[`CPS: 2,5 mg se <20 kg; 5 mg se ≥20 kg. Repetir a cada 20 min nas primeiras 3 doses conforme resposta.`,`CPS: <20 kg, 2,5 mg; ≥20 kg, 5 mg. A cada 20 min nas primeiras 3 doses, por resposta.`],[`Monitorizar taquicardia, tremor, hipocalemia e lactato. Não interpretar hiperlactatemia por beta-agonista automaticamente como piora do choque.`,`Vigiar taquicardia, tremor, hipocalemia/lactato. Hiperlactatemia por beta-agonista não implica piora do choque.`],[`Aerolin 5 mg/mL: aspirar 0,5 mL (2,5 mg) ou 1 mL (5 mg) e acrescentar respectivamente 2 ou 1,5 mL de SF 0,9%, para 2,5 mL finais. Via exclusivamente inalatória. Regime de exacerbação protocolar, diferente do regime usual da bula.`,`Aerolin 5 mg/mL: 0,5 mL (2,5 mg) + 2 mL SF 0,9%; ou 1 mL (5 mg) + 1,5 mL SF 0,9% = 2,5 mL FINAIS. SÓ INALATÓRIO. Exacerbação: regime protocolar, diferente do usual da bula.`],[`CHOP: 5–10 kg 7,5 mg/h; >10–20 kg 11,25 mg/h; >20 kg 15 mg/h. Abaixo de 5 kg não extrapolar esta tabela.`,`CHOP: 5–10 kg, 7,5 mg/h; >10–20 kg, 11,25 mg/h; >20 kg, 15 mg/h. Não extrapolar <5 kg.`],[`Não converter mg/h em mL/h sem conhecer a concentração final e o dispositivo. Monitorizar potássio, glicemia, lactato e ritmo.`,`mL/h exige concentração final/dispositivo conhecidos. Monitorar potássio, glicemia, lactato/ritmo.`],[`Informe a concentração final em mg/mL e confirme a compatibilidade do dispositivo no preparo calculado. A tela então mostra estoque, SF acrescentado, volume final para 1 h e mL/h de fornecimento ao nebulizador. Via exclusivamente inalatória; nunca IV.`,`Confirmar concentração final (mg/mL)/dispositivo para calcular estoque, SF, volume de 1 h e mL/h ao nebulizador. SÓ INALATÓRIO; nunca IV.`],[`CPS, maiores de 1 ano: 250 mcg por nebulização; a partir de 30 kg pode aumentar para 500 mcg. Repetir a cada 20–30 min por 3 doses iniciais, com salbutamol.`,`CPS, >1 ano: 250 mcg/nebulização; ≥30 kg, pode elevar a 500 mcg. A cada 20–30 min, 3 doses iniciais com salbutamol.`],[`Evitar contato do aerossol com os olhos; cuidado em glaucoma. 500 mcg em menores de 12 anos é protocolar/off-label para esta bula. Cautela em retenção urinária. Benefício é maior na fase inicial grave.`,`Evitar olhos; cautela no glaucoma/retenção urinária. 500 mcg <12 anos: protocolar/off-label nesta bula. Maior benefício na fase inicial grave.`],[`Aché 0,25 mg de brometo/mL: aspirar 1 ou 2 mL e completar com SF 0,9% para 4 mL finais. Força nominal do brometo, diferente de 0,2 mg/mL de base. Pode associar salbutamol quando compatível; não misturar com cromoglicato.`,`Aché 0,25 mg de brometo/mL: 1 ou 2 mL + SF 0,9% até 4 mL FINAIS. Brometo ≠ base 0,2 mg/mL. Salbutamol se compatível; não misturar cromoglicato.`],[`50 mg/kg EV, máximo 2.000 mg, em 15 min (esquema BCEHS do PDF, p. 420).`,`50 mg/kg EV, máx. 2.000 mg, em 15 min (BCEHS, PDF p. 420).`],[`Asma é uso off-label para sulfato VMG. Respeitar contraindicações do produto: insuficiência renal/cardíaca, hipermagnesemia e insuficiência respiratória grave. Monitorar pressão, ritmo, reflexos e diurese. Hipotensão, rubor e depressão neuromuscular. Não administrar a solução 50% sem diluição IV.`,`Asma: off-label VMG. Contraindicado: insuficiência renal/cardíaca, hipermagnesemia ou insuficiência respiratória grave. Monitorar pressão, ritmo, reflexos/diurese; risco de hipotensão, rubor e depressão neuromuscular. 50% EV: diluição obrigatória.`],[`Leve/moderado: 0,15 mg/kg VO, dose única, máximo 12 mg (NSW/ACI ECAT). Grave: 0,6 mg/kg VO/IV/IM, dose única, máximo 12 mg. Não repetir automaticamente.`,`NSW/ACI ECAT: leve/moderado, 0,15 mg/kg VO; grave, 0,6 mg/kg VO/IV/IM. Dose única, máx. 12 mg; sem repetição automática.`],[`Não esperar resposta imediata em obstrução grave; associar adrenalina nebulizada e manejo de via aérea quando indicado. Na ameaça à vida, priorizar resgate e via IV/IM conforme condição clínica. Em menores de 6 meses, considerar diagnósticos alternativos e avaliação especializada.`,`Obstrução grave: não aguardar efeito; adrenalina nebulizada/via aérea se indicadas. Risco de vida: priorizar resgate e IV/IM conforme clínica. <6 meses: diagnósticos alternativos/avaliação especializada.`],[`Selecionar a apresentação compatível com a via. Elixir somente oral; para IV, seguir diluição e velocidade do fabricante.`,`Elixir só VO; selecionar apresentação/via compatíveis. IV: diluição/velocidade do fabricante.`],[`5 mL da solução 1 mg/mL (5 mg), por nebulização, no regime CPS atual; não administrar este preparo IV. Via nebulizada off-label para a apresentação injetável.`,`CPS: 5 mL de 1 mg/mL (5 mg) nebulizados; NUNCA IV. Via nebulizada off-label para o injetável.`],[`Efeito é transitório. Observar recorrência por pelo menos 2–4 h e não agitar a criança; preparar equipe experiente se exaustão.`,`Efeito transitório: observar recorrência ≥2–4 h; não agitar criança. Exaustão: equipe experiente preparada.`],[`Usar o volume calculado no nebulizador; completar com SF apenas se o dispositivo exigir volume operacional maior.`,`Volume calculado no nebulizador; SF só se dispositivo exigir maior volume.`],[`2 mL/kg IV (0,2 g/kg) como abordagem inicial; reavaliar glicemia em 10–15 min e tratar recorrência.`,`Início: 2 mL/kg IV (0,2 g/kg); glicemia em 10–15 min, tratar recorrência.`],[`Evitar SG 50% periférica na criança. O Excel propunha concentrações muito hipertônicas; esta versão prioriza SG 10%.`,`Evitar SG 50% periférico pediátrico; priorizar SG 10% (Excel antigo: soluções hipertônicas).`],[`Se houver apenas SG 50%: 1 parte de SG 50% + 4 partes de diluente compatível → SG 10%. Preparar assepticamente e rotular.`,`Só SG 50% disponível: 1 parte SG 50% + 4 de diluente compatível → SG 10%. Assepsia/rotulagem.`],[`Hipocalcemia: 0,11 mmol/kg, máximo 4,4 mmol, em 10 min neste ramo. Hipercalemia com alteração de ECG: 0,15 mmol/kg, máximo 6,6 mmol; estável em 20 min; instável em pelo menos 5 min, prolongando quando necessário para não exceder 5 mL/min do produto brasileiro.`,`Hipocalcemia: 0,11 mmol/kg, máx. 4,4 mmol, em 10 min. Hipercalemia + ECG alterado: 0,15 mmol/kg, máx. 6,6 mmol; estável, 20 min; instável, ≥5 min, prolongar para ≤5 mL/min do produto BR.`],[`ECG contínuo, cálcio ionizado e inspeção do acesso. Extravasamento pode causar necrose. Evitar coadministração com bicarbonato, fosfato ou ceftriaxona. Não administrar IM/SC/intra-arterial. Na dose máxima, o limite da formulação prolonga a infusão instável além da faixa RCH de 2–5 min. Recém-nascidos têm esquema próprio.`,`ECG contínuo, cálcio ionizado/acesso; extravasamento pode causar necrose. Não coadministrar bicarbonato, fosfato/ceftriaxona. NUNCA IM/SC/intra-arterial. Dose máxima: limite BR prolonga infusão instável além de 2–5 min RCH. RN: esquema próprio.`],[`Hipocalcemia: aspirar D/0,2325 mL e completar com SF 0,9% ou SG 5% para D/0,044 mL finais (0,044 mmol/mL). Hipercalemia: o cálculo para solução 10% exige acesso amplo, seguro e monitorizado. Não transpor volumes do produto internacional 0,22 mmol/mL.`,`Hipocalcemia: D/0,2325 mL + SF 0,9% ou SG 5% até D/0,044 mL FINAIS → 0,044 mmol/mL. Hipercalemia a 10%: acesso amplo/seguro/monitorizado. Não usar volumes do produto 0,22 mmol/mL.`],[`Exemplo de dose inicial 1 mEq/kg IV, com velocidade e repetição orientadas pela indicação.`,`Exemplo inicial: 1 mEq/kg IV; velocidade/repetição conforme indicação.`],[`Não é droga de rotina na PCR pediátrica. Ventilação inadequada favorece geração de CO₂; vigiar sódio, osmolaridade, pH e extravasamento.`,`Não rotineiro na PCR pediátrica. Ventilação inadequada favorece CO₂; vigiar sódio, osmolaridade, pH/extravasamento.`],[`Para 0,5 mEq/mL: misturar volumes iguais de bicarbonato 8,4% e água para injetáveis. Selecionar contexto e tempo prescrito no preparo calculado para obter mL/h; correção lenta de acidose não recebe velocidade de emergência.`,`Bicarbonato 8,4% + igual volume de água para injetáveis → 0,5 mEq/mL. mL/h exige contexto/tempo prescrito; acidose lenta não usa velocidade de emergência.`],[`Criança sem dependência conhecida: 0,1 mg/kg IV/IO/IM; máximo 2 mg por dose, repetir a cada 2–3 min conforme resposta. A via intranasal exige dispositivo e concentração próprios; não usar o volume calculado para a solução injetável 0,4 mg/mL por via nasal.`,`Sem dependência conhecida: 0,1 mg/kg IV/IO/IM, máx. 2 mg/dose; repetir a cada 2–3 min por resposta. IN exige dispositivo/concentração próprios; não usar o volume da solução injetável 0,4 mg/mL por via nasal.`],[`Em dependência crônica, iniciar 0,001–0,01 mg/kg e titular à ventilação para reduzir abstinência, dor e descarga simpática.`,`Dependência crônica: início 0,001–0,01 mg/kg, titular à ventilação; reduzir abstinência, dor/descarga simpática.`],[`Para titulação fina em dependência de opioide, diluir conforme protocolo e usar doses menores incrementais.`,`Dependência de opioide: diluição protocolar e pequenas doses incrementais.`],[`LAST: até 70 kg, bolus de aproximadamente 1,5 mL/kg em 2–3 min e infusão 0,25 mL/kg/min (15 mL/kg/h). Acima de 70 kg, bolus aproximado de 100 mL em 2–3 min e 250 mL em 15–20 min (750–1.000 mL/h). Se instabilidade persistir, repetir bolus e dobrar infusão. Continuar por mais de 15 min após estabilização, respeitando total acumulado máximo 12 mL/kg.`,`LAST: ≤70 kg, bolus ≈1,5 mL/kg em 2–3 min + 0,25 mL/kg/min (15 mL/kg/h); >70 kg, ≈100 mL em 2–3 min + 250 mL em 15–20 min (750–1.000 mL/h). Instabilidade persistente: repetir bolus/dobrar infusão. Manter >15 min após estabilização; total máx. 12 mL/kg.`],[`Emulsão lipídica 20%, sem diluição. Resgate de LAST segue algoritmo específico; não extrapolar automaticamente a outros tóxicos. Controlar volume acumulado inclusive bolus e infusões.`,`20% sem diluir. LAST: algoritmo próprio; não extrapolar a outros tóxicos. Somar volumes de bolus/infusões.`],[`Não diluir. Usar equipo exclusivo e checar produto 20%.`,`20%, sem diluir; equipo exclusivo/conferir produto.`],[`0,05–0,1 U/kg/h IV, sem bolus. Iniciar geralmente 1 h após fluidos, conforme protocolo e potássio.`,`0,05–0,1 U/kg/h IV; NUNCA bolus. Início geralmente após 1 h de fluidos, por protocolo/potássio.`],[`Nunca usar bolus de insulina na CAD pediátrica. Monitorizar glicemia, potássio, sódio corrigido, osmolaridade e sinais de lesão cerebral.`,`CAD pediátrica: NUNCA bolus. Monitorar glicemia, potássio, sódio corrigido, osmolaridade/lesão cerebral.`],[`Aspirar 1 mL de insulina regular 100 U/mL (100 U) e completar com SF 0,9% para volume final de 100 mL → 1 U/mL. Cebar o equipo conforme protocolo para reduzir adsorção.`,`1 mL de regular 100 U/mL (100 U) + SF 0,9% até 100 mL FINAIS → 1 U/mL. Cebar equipo conforme protocolo contra adsorção.`],[`IWK: <12 anos, ataque 15 mg/kg IV (máx. 1 g), depois 2 mg/kg/h (máx. 125 mg/h); ≥12 anos, ataque fixo 1 g e manutenção 125 mg/h. Ataque em pelo menos 10 min, sem exceder 50 mg/min; manutenção por até 8 h ou até cessar sangramento. Regime protocolar de trauma, diferente da posologia pediátrica geral da bula BR.`,`IWK: <12 anos, ataque 15 mg/kg IV (máx. 1 g) + 2 mg/kg/h (máx. 125 mg/h); ≥12 anos, 1 g + 125 mg/h. Ataque ≥10 min E ≤50 mg/min; manutenção ≤8 h ou até cessar sangramento. Trauma: protocolar, diferente da posologia pediátrica geral BR.`],[`Não usar automaticamente em todo trauma nem em CIVD sem indicação específica. Ajustar na disfunção renal e conferir concentração/velocidade.`,`Não automático em trauma/CIVD sem indicação. Ajuste renal; conferir concentração/velocidade.`],[`Ataque: diluir em SF 0,9%; mínimo 10 min, prolongar para respeitar 50 mg/min (bula Fresenius Kabi). Manutenção: exemplo 1 g e completar para 100 mL → 10 mg/mL.`,`Ataque: SF 0,9%, ≥10 min E ≤50 mg/min (Fresenius Kabi). Manutenção: 1 g até 100 mL FINAIS → 10 mg/mL.`],[`Sepse sem SNC: referência inicial 50 mg/kg (máx. 2 g). Meningite: 100 mg/kg (máx. 4 g), podendo dividir 12/12 h conforme protocolo.`,`Sepse sem SNC: inicial 50 mg/kg (máx. 2 g). Meningite: 100 mg/kg (máx. 4 g), divisível 12/12 h conforme protocolo.`],[`IDADE É OBRIGATÓRIA para validar este item. Evitar no neonato com hiperbilirrubinemia e em neonatos que recebem cálcio IV; em neonatos, usar protocolo específico. Colher culturas sem atrasar antibiótico no choque.`,`Idade obrigatória. RN: protocolo próprio; evitar se hiperbilirrubinemia/cálcio IV. Culturas sem atrasar antibiótico no choque.`],[`O preparo calculado exige confirmar Rocefin IV e selecionar indicação/intervalo; utiliza a tabela de reconstituição por peso da bula Roche, final 50 mg/mL em SF sem cálcio, em 30 min. Outro fabricante exige seu próprio preparo. O total diário de meningite é dividido antes do volume no esquema q12h.`,`Confirmar Rocefin IV, indicação/intervalo; reconstituição por peso (Roche), 50 mg/mL em SF sem cálcio, 30 min. Outro fabricante: preparo próprio. Meningite q12h: dividir total diário antes de calcular volume.`],[`50 mg/kg/dose IV a cada 8 h em neutropenia febril ou pneumonia grave por Pseudomonas; máximo 2 g/dose.`,`Neutropenia febril/pneumonia grave por Pseudomonas: 50 mg/kg/dose IV a cada 8 h, máx. 2 g/dose.`],[`O preparo calculado exige confirmar cefepima Fresenius Kabi: FA 1 ou 2 g +10 mL de água para injetáveis, aproximadamente 90 ou 161 mg/mL. Diluição pediátrica protocolar a 20 mg/mL em SF, em 30 min, dentro do limite PCH ≤40 mg/mL; difere da bolsa de 100 mL da bula brasileira. Outro fabricante exige conciliação própria.`,`Confirmar Fresenius Kabi: FA 1/2 g +10 mL água para injetáveis → ≈90/161 mg/mL. Diluição pediátrica protocolar: 20 mg/mL em SF, 30 min (PCH ≤40 mg/mL; bula BR: bolsa 100 mL). Outro fabricante: conciliar preparo.`],[`Meningite em >3 meses: 40 mg/kg/dose IV a cada 8 h; máximo 2 g/dose; infusão em 15–30 min.`,`Meningite >3 meses: 40 mg/kg/dose IV a cada 8 h, máx. 2 g/dose, em 15–30 min.`],[`O preparo calculado exige confirmar Meronem IV: FA 500 mg +10 mL ou 1 g +20 mL de água para injetáveis, aproximadamente 50 mg/mL; retirar a dose e completar em SF para 20 mg/mL, em 30 min. Uso imediato; estabilidade físico-química não garante esterilidade. Outro fabricante exige conciliação própria.`,`Confirmar Meronem IV: FA 500 mg +10 mL ou 1 g +20 mL água para injetáveis → ≈50 mg/mL. Dose + SF até 20 mg/mL, 30 min. Uso imediato; estabilidade não garante esterilidade. Outro fabricante: conciliar preparo.`],[`Crianças ≥4 semanas: dose inicial 15 mg/kg IV, máximo inicial 750 mg. Neste ramo PCH, 6/6 h com função renal normal; avaliar função renal e níveis antes de definir as doses seguintes. Infundir em pelo menos 60 min e não exceder 10 mg/min.`,`≥4 semanas: início 15 mg/kg IV, máx. 750 mg. PCH: 6/6 h se função renal normal; reavaliar rim/níveis antes das próximas doses. ≥60 min E ≤10 mg/min.`],[`PCH 15 mg/kg q6 h difere dos 10 mg/kg q6 h usuais da bula Novamicin BR; a seleção é protocolar. Não administrar diretamente IV; separar de betalactâmicos incompatíveis, incluindo ceftriaxona, com lavagem do acesso. Não aplicar o ramo pediátrico ao recém-nascido. 10 mg/mL apenas com restrição hídrica E acesso venoso central. Se reação relacionada à infusão, prolongar futuras infusões para pelo menos 2 h. Em infecção invasiva por MRSA, individualizar por exposição e função renal.`,`PCH 15 mg/kg q6 h é protocolar (Novamicin BR usual: 10 mg/kg q6 h). Não IV direto; separar betalactâmicos incompatíveis/ceftriaxona com flush. RN: outro esquema. 10 mg/mL só com restrição hídrica E acesso central. Reação à infusão: próximas doses em ≥2 h. MRSA invasivo: individualizar por exposição/rim.`],[`Frasco 500 mg + 10 mL de água para injetáveis, ou 1 g + 20 mL: 50 mg/mL. Aspirar dose/50 mL e completar com SF 0,9% ou SG 5% para volume final dose/5 mL. Solução reconstituída não é a solução final de infusão.`,`FA 500 mg + 10 mL água para injetáveis ou 1 g + 20 mL → 50 mg/mL. Dose/50 mL + SF 0,9% ou SG 5% até dose/5 mL FINAIS. Reconstituída ≠ solução final.`],[`Choque: idealmente ≤1 h. Sepse provável sem choque: investigação rápida e início idealmente ≤3 h se a suspeita se sustenta.`,`Choque: idealmente ≤1 h. Sem choque: investigar rapidamente; se sepse provável persistir, iniciar idealmente ≤3 h.`],[`A meta não autoriza antibiótico aleatório: cobertura inadequada também é dano. Registrar horário do reconhecimento e da primeira dose.`,`Cobertura apropriada, não antibiótico aleatório. Registrar reconhecimento/primeira dose.`],[`Definir esquema pelo foco, idade, colonização, acesso, função renal e antibiograma local.`,`Esquema por foco, idade, colonização, acesso, função renal/antibiograma local.`]],c=[[`Volume a administrar após completar com SF para40mg/mL`,`Solução final: 40mg/mL em SF.`],[`Usar exclusivamente solução já preparada e rotulada a 0,1 mg/mL; conferir concentração antes de aspirar. A ampola de estoque não está liberada por este contrato.`,`Só solução preparada/rotulada 0,1 mg/mL; conferir antes de aspirar. Ampola estoque não liberada.`],[`Bolus IV/IO na PCR, seguido de flush; não é infusão contínua em bomba.`,`PCR: bolus IV/IO + flush; sem BIC.`],[`Bolus IV/IO na PCR; não é infusão contínua em bomba.`,`PCR: bolus IV/IO; sem BIC.`],[`Bolus IV/IO; reavaliar antes de repetir. Não é infusão contínua em bomba.`,`Bolus IV/IO; reavaliar antes de repetir. Sem BIC.`],[`Push IV ultrarrápido e flush imediato. Não programar em mL/h.`,`Push IV ultrarrápido + flush imediato; sem mL/h.`],[`Bolus IV seletivo antes da IOT; não é infusão contínua em bomba.`,`Pré-IOT seletivo: bolus IV; sem BIC.`],[`Indução IV; volume de dose única, não infusão contínua em bomba.`,`Indução IV, dose única; sem BIC.`],[`Indução IV titulada; não transpor este ramo para sedação contínua pediátrica.`,`Indução IV titulada; não usar para sedação contínua pediátrica.`],[`Bolus IV para sequência rápida, após sedação; não usar a vazão do ramo de infusão.`,`Sequência rápida: bolus IV após sedação; não usar vazão de infusão.`],[`Aplicação IM na anafilaxia; mL/h não se aplica. Não administrar por bomba IV.`,`Anafilaxia: IM; nunca BIC IV.`],[`Aerossol com espaçador; mL/h não se aplica.`,`Aerossol/espaçador; sem mL/h.`],[`Nebulização intermitente; completar o volume somente conforme o dispositivo. mL/h de bomba IV não se aplica.`,`Nebulização intermitente; completar volume conforme dispositivo. Nunca BIC IV.`],[`Nebulização intermitente; mL/h de bomba IV não se aplica.`,`Nebulização intermitente; nunca BIC IV.`],[`Nebulização; mL/h de bomba IV não se aplica.`,`Nebulização; nunca BIC IV.`],[`Dose IV de resgate da hipoglicemia, com reavaliação; não é taxa de manutenção contínua.`,`Resgate IV da hipoglicemia; reavaliar. Não é manutenção contínua.`],[`Dose de resgate IV/IO/IM; esta apresentação não define uma infusão contínua ou dispositivo intranasal.`,`Resgate IV/IO/IM; sem BIC/IN para esta apresentação.`],[`PCR sem pulso: protocolo pediátrico CHEO. A bula Fresenius Kabi consultada contraindica uso em crianças e contém álcool benzílico; PALS/CHEO não validam automaticamente esse fabricante. Conciliar produto/excipientes e contexto pela equipe responsável. O volume a 1 mg/mL pode ser elevado: avaliar carga hídrica e logística de administração na ressuscitação. Não transpor bolus para ritmo com pulso; não administrar ampola pura.`,`PCR sem pulso (CHEO). Fresenius Kabi: contraindicado em crianças/álcool benzílico; protocolo não valida fabricante. Equipe deve conciliar produto/excipientes/contexto. 1 mg/mL: avaliar carga hídrica/logística. Com pulso: outro regime. Não usar ampola pura.`],[`Administrar esta dose IV/IO em bolus apenas no ramo de PCR sem pulso; não há mL/h contínuo. Etapas separadas, sem repetição automática.`,`Bolus IV/IO só na PCR sem pulso; sem BIC/repetição automática.`],[`Midazolam Fresenius Kabi: regime para convulsão/IN é protocolar/off-label; não atribuir este regime à indicação de sedação da bula. IV: solução final 1 mg/mL, pelo menos 5 min; prolongar para dose em mg ÷ 1 mg/min se a dose exceder 5 mg (limite CHEO 1 mg/min). Monitorar ventilação, pressão e ritmo. As doses e vias são alternativas, não faixa mínima/máxima de infusão contínua.`,`Midazolam Fresenius: convulsão/IN protocolar/off-label, distinto da sedação em bula. IV: 1 mg/mL, ≥5 min; dose >5 mg: tempo = dose ÷ 1 mg/min (CHEO). Monitorar ventilação/pressão/ritmo. Vias/doses alternativas; não faixa de BIC.`],[`Regime anticonvulsivante CHEO protocolar/off-label em relação às indicações da bula; IN também é via off-label. Não utilizar apresentação 1 mg/mL neste ramo.`,`Convulsão CHEO/IN: protocolar/off-label. Não usar 1 mg/mL neste ramo.`],[`por via intranasal, sem diluir; dividir metade em cada narina, com atomizador apropriado. Uso off-label. Reavaliar ventilação; não somar às alternativas IV/IM. mL/h não se aplica.`,`IN sem diluir, metade/narina com atomizador. Off-label; reavaliar ventilação. Não somar IV/IM; sem mL/h.`],[`IM em músculo grande; confirmar volume adequado ao local e à idade. Reavaliar ventilação; não somar às alternativas IV/IN. mL/h não se aplica.`,`IM em músculo grande; volume por local/idade. Reavaliar ventilação; não somar IV/IN; sem mL/h.`],[`Antara IV 100 mg/mL: completar a dose em SF 0,9% para concentração final 15 mg/mL e infundir em 15 min, conforme limite da bula brasileira para volume pediátrico reduzido. A carga de 60 mg/kg (máx. 4.500 mg) no estado de mal é protocolar/off-label; a bula não indica ataque para estado de mal nem uso abaixo de 6 anos. Não administrar puro; uso imediato, avaliar função renal. A concentração CHEO de 20/40 mg/mL não é transposta para este produto.`,`Antara 100 mg/mL → 15 mg/mL em SF 0,9%, 15 min (bula BR, volume reduzido). Ataque 60 mg/kg, máx. 4.500 mg, no estado de mal/<6 anos: protocolar/off-label. Não usar puro; uso imediato/avaliar rim. Não aplicar CHEO 20/40 mg/mL.`],[`Fenital 50 mg/mL: ataque 20 mg/kg do protocolo CHEO, diferente dos 10–15 mg/kg da bula brasileira. Diluição apenas quando necessária; a bula alerta para precipitação, admite SF 0,9% e exige filtro 0,22 micra. Não atribuir estabilidade estrangeira ao produto BR; preparar imediatamente antes da dose.`,`Fenital 50 mg/mL: CHEO 20 mg/kg (bula BR: 10–15 mg/kg). Diluir só se necessário: risco de precipitação; SF 0,9%/filtro 0,22 micra. Preparo imediato; estabilidade estrangeira não validada no produto BR.`],[`Não usar SG; filtro em linha de 0,22 micra e flush com SF antes/depois.`,`Sem SG; filtro 0,22 micra + flush SF antes/depois.`],[`Velocidade ≤1 mg/kg/min e ≤25 mg/min, inclusive na cardiopatia. ECG, pressão e acesso monitorizados; reduzir/interromper se hipotensão ou arritmia. Esta é dose única, não faixa de manutenção.`,`≤1 mg/kg/min E ≤25 mg/min, inclusive cardiopatia. Monitorar ECG/pressão/acesso; hipotensão/arritmia: reduzir/parar. Dose única, não manutenção.`],[`Usar somente NaCl 3% pronto/preparado e rotulado; não acrescentar diluente.`,`NaCl 3% pronto/preparado e rotulado; sem diluir.`],[`Somente em UTI, titulada à pressão intracraniana/sódio; não somar automaticamente aos bolus.`,`Só UTI; titular por pressão intracraniana/sódio. Não somar automaticamente a bolus.`],[`Manitol 20%: não diluir; inspecionar cristais e utilizar filtro conforme produto.`,`Manitol 20%: sem diluir; inspecionar cristais/filtro conforme produto.`],[`Reavaliar hemodinâmica, função renal e osmolaridade.`,`Reavaliar hemodinâmica/rim/osmolaridade.`],[`Emulsão lipídica IV 20% para LAST: não diluir; via/equipo exclusivos.`,`LAST: emulsão IV 20%, sem diluir; via/equipo exclusivos.`],[`Reavaliar após estabilização; respeitar algoritmo ASRA e teto acumulado.`,`Após estabilização: reavaliar, seguir ASRA/teto acumulado.`],[`Somar todos os bolus e infusões; isto é volume total, não mL/h.`,`Total de bolus + infusões; volume, não mL/h.`],[`não manter esta vazão como infusão contínua.`,`não manter como BIC.`],[`Administrar somente VO; mL/h não se aplica.`,`Só VO; sem mL/h.`],[`IV/IM apenas no crupe grave; não presumir tempo de bomba ou diluição do fabricante.`,`IV/IM só no crupe grave; tempo/diluição dependem do fabricante.`],[`Ataque e manutenção usam preparos separados a 10 mg/mL. Regime IWK por idade, protocolar/off-label em relação à dose pediátrica geral da bula BR; limite de 50 mg/min da bula Fresenius Kabi preservado. A dose de manutenção de CHEO é diferente e não substitui a fonte IWK de trauma.`,`Ataque/manutenção: preparos separados 10 mg/mL. Trauma IWK por idade: protocolar/off-label perante bula BR; ≤50 mg/min Fresenius. Manutenção CHEO diferente: não substituir IWK.`],[`Não somar as vazões do ataque e manutenção. Ajustar se disfunção renal; conferir protocolo de trauma.`,`Não somar vazões; ajuste renal/protocolo de trauma.`],[`Meronem em SF: usar imediatamente; estabilidade físico-química até 3 h a ≤25 °C não assegura esterilidade. Não congelar.`,`Meronem/SF: uso imediato; estabilidade até 3 h a ≤25 °C não garante esterilidade. Não congelar.`],[`Não usar diluente IM com lidocaína. Avaliar ajuste renal antes de repetir doses.`,`Sem diluente IM/lidocaína; avaliar ajuste renal antes de repetir.`],[`Nunca diluir com cálcio/Ringer ou coadministrar com cálcio; lavar a via entre infusões sequenciais quando permitidas. Se depuração de creatinina <10 mL/min, a bula limita a dose diária a 2 g; este cálculo não aplica ajuste renal automático.`,`Sem cálcio/Ringer/coadministração com cálcio; flush entre infusões sequenciais permitidas. Depuração <10 mL/min: máx. 2 g/dia (bula); ajuste renal não automático.`],[`Não informados: indicação específica, tempo prescrito e quantidade já administrada nas últimas 24 h. Na correção de acidose, também faltam dose prescrita após gasometria e avaliação correspondente; não assumir histórico zero.`,`Faltam indicação, tempo e acumulado em 24 h; acidose: também dose prescrita/avaliação após gasometria. Não presumir histórico zero.`],[`Selecione indicação e tempo prescrito. Emergência específica e correção lenta de acidose não compartilham a mesma velocidade.`,`Faltam indicação e tempo prescrito; emergência/acidose lenta têm velocidades distintas.`],[`Informe o tempo prescrito da alíquota em minutos, conforme tipo de choque e reavaliação.`,`Falta tempo prescrito (min), por tipo de choque/reavaliação.`],[`Informe a concentração final (mg/mL) validada para o nebulizador e confirme o dispositivo. A vazão é do fornecimento ao nebulizador, nunca IV.`,`Faltam concentração validada (mg/mL)/dispositivo. Vazão ao nebulizador, NUNCA IV.`],[`Selecione sepse ou meningite e o intervalo. mg/dia não é automaticamente mg/dose.`,`Selecionar sepse/meningite e intervalo; mg/dia ≠ mg/dose.`],[`Criança sem insuficiência renal; regime pediátrico de até 35 h, com monitorização hemodinâmica.`,`Sem insuficiência renal; ≤35 h, monitorização hemodinâmica.`],[`Produto Fenocris: paciente não é recém-nascido nem criança do sexo feminino; excluídas porfiria e insuficiência renal, hepática ou respiratória grave.`,`Fenocris: excluir RN, meninas, porfiria e insuficiência renal/hepática/respiratória grave.`],[`Paciente sem dependência crônica de opioide; este ramo é o resgate de 0,1 mg/kg, não a titulação em dependência.`,`Ausência de dependência crônica; resgate 0,1 mg/kg, não titulação na dependência.`],[`CAD confirmada; pelo menos 1 h de fluidos e potássio conferido segundo ISPAD antes da insulina; hipocalemia corrigida. Não usar bolus.`,`CAD confirmada, ≥1 h de fluidos/potássio conferido (ISPAD), hipocalemia corrigida. Sem bolus.`],[`LAST confirmado/suspeito no algoritmo ASRA; produto IV 20%, via exclusiva e volume acumulado de bolus/infusões conferido contra 12 mL/kg.`,`LAST confirmado/suspeito (ASRA); IV 20%, via exclusiva, bolus + infusões ≤12 mL/kg.`],[`Conferir ECG, pressão, perfusão e extravasamento; evitar alcalinos. A seleção anterior 5–20 não era a faixa integral da fonte.`,`ECG/pressão/perfusão/extravasamento; evitar alcalinos. Seleção antiga 5–20: faixa incompleta da fonte.`],[`10 é extremo da faixa, não máximo absoluto universal. Incrementos de 0,5 mcg/kg/h dependem da resposta.`,`10: extremo da faixa, não teto universal. Incrementos 0,5 mcg/kg/h por resposta.`],[`Unidade por HORA, nunca por minuto. Avaliar função renal/hepática; monitorar ventilação, sedação e pressão, com suporte respiratório disponível.`,`Por HORA, nunca minuto. Avaliar rim/fígado; monitorar ventilação/sedação/pressão, com suporte respiratório.`],[`0,04 é máximo usual, não teto absoluto. Incrementos de 0,01 mg/kg/h a cada 2–4 h dependem da resposta.`,`0,04: máximo usual, não teto absoluto. +0,01 mg/kg/h a cada 2–4 h por resposta.`],[`Uso pediátrico off-label perante a bula adulta Dimorf. Individualizar função renal/hepática, instabilidade, ventilação e sedação.`,`Pediatria off-label (Dimorf adulto); individualizar por rim/fígado, instabilidade, ventilação/sedação.`],[`Concentração CHEO 1 mg/mL em SF; preparo calculado para o estoque selecionado. Conferir via aérea, ventilação, pressão e função orgânica.`,`CHEO 1 mg/mL em SF; preparo calculado. Conferir via aérea/ventilação/pressão/função orgânica.`],[`0,5 é extremo da faixa deste contexto, não máximo universal.`,`0,5: extremo deste ramo, não teto universal.`],[`4 mcg/mL em SF: receita proporcional à bula Precedex. Uso pediátrico off-label; a bula brasileira não recomenda abaixo de 18 anos.`,`4 mcg/mL em SF: proporcional à bula Precedex. Pediatria off-label; bula BR não recomenda <18 anos.`],[`Individualizar função hepática; monitorar bradicardia e hipotensão. Não gerar bolus de rotina nem tratar o limite inferior como início obrigatório.`,`Individualizar por fígado; monitorar bradicardia/hipotensão. Sem bolus rotineiro; limite inferior não é início obrigatório.`],[`Bloqueio neuromuscular contínuo em UTI pediátrica com ventilação e sedoanalgesia prévias; não seda nem trata dor.`,`Bloqueio contínuo em UTI pediátrica; ventilação/sedoanalgesia prévias. Não seda nem trata dor.`],[`Equivale a 5–10 mcg/kg/min. Sem início único na linha consultada.`,`5–10 mcg/kg/min; sem início único na fonte.`],[`Tabela suplementar, página 82: 15 mcg/kg/min. Máximo usual, não teto absoluto.`,`Suplemento p. 82: 15 mcg/kg/min; máximo usual, não teto absoluto.`],[`Receita Queensland: 100 mg em 50 mL finais. Volumes do estoque 10 mg/mL e SG 5% calculados.`,`Queensland: 100 mg/50 mL FINAIS; volumes calculados para estoque 10 mg/mL/SG 5%.`],[`Concentração 200 mcg/mL sustentada no SmPC Tillomed, não no padrão CHEO 100/400; receita escalada por cálculo.`,`200 mcg/mL: SmPC Tillomed, não CHEO 100/400; preparo calculado.`],[`Monitorar pressão, ECG, potássio e função renal; respeitar incompatibilidades do produto, inclusive furosemida, bumetanida e bicarbonato.`,`Monitorar pressão/ECG/potássio/rim. Incompatível com furosemida, bumetanida/bicarbonato; conferir produto.`],[`Estado de mal epiléptico refratário pediátrico, com neurologia, via aérea e EEG contínuo; não usar para sedação comum.`,`Estado de mal refratário pediátrico; neurologia/via aérea/EEG contínuo. Não usar na sedação comum.`],[`Considerar outro agente se sem resposta acima de 1 mg/kg/h; acima de 50 mg/h a fonte alerta dose excessiva, sem definir teto absoluto formal.`,`Sem resposta >1 mg/kg/h: considerar outro agente. >50 mg/h: alerta de excesso, não teto formal.`],[`CAD pediátrica, após pelo menos 1 h de fluidos e avaliação/correção do potássio; nunca bolus. Não extrapolar a HHS ou hipercalemia isolada.`,`CAD pediátrica: ≥1 h de fluidos/potássio avaliado/corrigido. NUNCA bolus. Não extrapolar a HHS/hipercalemia isolada.`],[`Menor de 5 anos, transferência com monitorização limitada ou glicemia <15 mmol/L; avaliar o contexto real.`,`<5 anos, transferência com monitorização limitada ou glicemia <15 mmol/L; confirmar contexto.`],[`Alternativa à opção de 0,05; não somar. Não são mínimo e máximo universais.`,`Alternativa a 0,05; não somar. Não são limites universais.`],[`1 U/mL em SF conforme RCH; preparo de 100 mL é escala aritmética da receita de 50 mL. Conferir cebagem/adsorção, equipo e protocolo local.`,`RCH 1 U/mL em SF; 100 mL escalados de 50 mL. Conferir cebagem/adsorção/equipo/protocolo.`],[`Faltam potássio, glicemia e histórico de fluidos: nenhuma opção é selecionada automaticamente. Hipoglicemia persistente pode requerer outra dose; 0,05 não é mínimo absoluto.`,`Potássio/glicemia/fluidos não informados: sem seleção automática. Hipoglicemia persistente: reavaliar dose; 0,05 não é mínimo absoluto.`],[`por pelo menos`,`por ≥`],[`; programar o volume final total`,`; limitar ao volume FINAL`],[`encerrar após o volume da dose`,`encerrar ao completar a dose`],[`da apresentação selecionada`,`da apresentação`],[`retirar somente o volume calculado`,`retirar só o volume calculado`],[`retirar somente a dose abaixo`,`retirar só a dose`],[`para obter 50 mg/mL; confirmar bula do produto`,`→ 50 mg/mL; conferir bula`],[`Reconstituir cada frasco com`,`Por frasco:`],[`reconstituir cada frasco de`,`por frasco de`],[`incluindo deslocamento do pó`,`com deslocamento do pó`],[`volume máximo administrado`,`volume máximo`],[`Conferência reversa:`,`Conferência:`],[`Preparo proporcional e separado para cada`,`Preparo separado/proporcional por`]],l=[...s,...c,[`Após choques e RCP de alta qualidade em FV/TV sem pulso refratária. Alternativa à lidocaína; não somar rotineiramente as duas.`,`FV/TV sem pulso refratária após choques/RCP de qualidade. Alternativa à lidocaína; não associar rotineiramente.`],[`Bradicardia com pulso por aumento do tônus vagal ou bloqueio AV primário. Não substitui ventilação/oxigenação nem adrenalina na bradicardia com má perfusão.`,`Bradicardia com pulso por tônus vagal/bloqueio AV primário. Não substitui ventilação, oxigenação ou adrenalina se má perfusão.`],[`TSV regular. Considerar em taquicardia regular monomórfica de QRS largo quando o diagnóstico for incerto e houver monitorização especializada.`,`TSV regular; considerar em taquicardia regular monomórfica de QRS largo, diagnóstico incerto e monitorização especializada.`],[`Reposição em choque quando indicada. Em choque hemorrágico, priorizar controle de sangramento e hemocomponentes conforme protocolo.`,`Reposição no choque, se indicada. Hemorrágico: priorizar hemostasia e hemocomponentes conforme protocolo.`],[`Pode ser razoável antes da IOT em lactentes/crianças com risco de bradicardia, uso de succinilcolina ou quando a bradicardia mediada pelo vago é provável.`,`Pré-IOT em lactentes/crianças selecionados: risco de bradicardia, succinilcolina ou estímulo vagal provável.`],[`Analgesia e atenuação da resposta à laringoscopia quando a hemodinâmica permite. Não é o agente de indução isolado.`,`Analgesia/atenuação da laringoscopia, se hemodinâmica permitir. Não usar como indução isolada.`],[`Indução em criança hemodinamicamente estável, quando houver justificativa e experiência. Não é escolha padrão no choque.`,`Indução em criança estável, com justificativa/experiência. Não é padrão no choque.`],[`Bloqueio neuromuscular para sequência rápida após sedação/indução adequada.`,`Bloqueio para sequência rápida após sedação/indução adequada.`],[`Vasoativo de primeira linha possível no choque séptico refratário a fluidos, sobretudo no fenótipo vasoplégico.`,`Opção de primeira linha no choque séptico refratário a fluidos, sobretudo vasoplégico.`],[`Vasoativo de primeira linha possível no choque séptico refratário a fluidos, especialmente quando predomina baixo débito; também em hipotensão pós-PCR selecionada.`,`Opção de primeira linha no choque séptico refratário a fluidos, sobretudo baixo débito; hipotensão pós-PCR selecionada.`],[`Suporte inotrópico em disfunção miocárdica/baixo débito quando a pressão permite; não corrige vasoplegia isolada.`,`Inotropia na disfunção miocárdica/baixo débito, se pressão permitir; não corrige vasoplegia isolada.`],[`Inodilatador em disfunção miocárdica ou pós-operatório cardíaco selecionado, com monitorização intensiva.`,`Inodilatação na disfunção miocárdica/pós-operatório cardíaco selecionado; monitorização intensiva.`],[`Agente alternativo em contextos selecionados; adrenalina ou noradrenalina são preferidas no choque séptico pediátrico refratário a fluidos.`,`Alternativa selecionada; preferir adrenalina/noradrenalina no choque séptico pediátrico refratário a fluidos.`],[`Analgesia contínua no paciente ventilado, com escala de dor/sedação e metas diárias. Tratar dor antes de intensificar hipnótico.`,`Analgesia contínua em VM; escala de dor/sedação e metas diárias. Tratar dor antes de ampliar hipnótico.`],[`Analgesia em paciente ventilado, quando a liberação de histamina e a depuração renal não forem limitantes.`,`Analgesia em VM, se liberação de histamina/depuração renal não limitarem.`],[`Sedação de paciente ventilado quando medidas não farmacológicas e analgesia isolada são insuficientes.`,`Sedação em VM se medidas não farmacológicas e analgesia forem insuficientes.`],[`Adjuvante de sedação, inclusive para facilitar desmame, quando bradicardia e hipotensão forem aceitáveis.`,`Sedação adjuvante/desmame, se risco de bradicardia/hipotensão aceitável.`],[`Assincronia grave ou estratégia ventilatória em paciente selecionado, após otimizar analgesia, sedação e ventilador.`,`Assincronia grave/estratégia ventilatória selecionada após otimizar analgesia, sedação e ventilador.`],[`Estado de mal epiléptico refratário após benzodiazepínico e segunda linha, em UTI com EEG contínuo e ventilação preparada.`,`Estado de mal refratário após benzodiazepínico/segunda linha; UTI, EEG contínuo e ventilação preparada.`],[`Crise convulsiva com duração ≥5 min ou crises seriadas sem recuperação. Escolher uma via; não somar as doses das duas linhas.`,`Crise ≥5 min ou seriadas sem recuperação. Escolher uma via; não somar doses.`],[`Estado de mal estabelecido após benzodiazepínico adequado. Escolher uma opção de segunda linha conforme etiologia e paciente.`,`Estado de mal após benzodiazepínico adequado; escolher segunda linha conforme etiologia/paciente.`],[`Bolus para hipertensão intracraniana em TCE pediátrico grave, junto a medidas de neuroproteção e monitorização.`,`Bolus na hipertensão intracraniana do TCE pediátrico grave, com neuroproteção/monitorização.`],[`Alternativa osmótica em deterioração neurológica com suspeita de hipertensão intracraniana, conforme hemodinâmica e equipe de neurocritical care.`,`Alternativa osmótica na deterioração com suspeita de hipertensão intracraniana; avaliar hemodinâmica com equipe neurointensiva.`],[`Anafilaxia clínica. Aplicar na face anterolateral da coxa; repetir se necessário enquanto se trata via aérea, oxigenação e choque.`,`Anafilaxia: IM na coxa anterolateral; repetir se necessário. Tratar via aérea, oxigenação e choque.`],[`Broncoespasmo; preferir aerossol dosimetrado com espaçador quando a criança coopera e a gravidade permite.`,`Broncoespasmo: preferir aerossol com espaçador se cooperação/gravidade permitirem.`],[`Exacerbação com necessidade de nebulização, oxigênio ou quando a técnica com espaçador é inviável.`,`Exacerbação: nebulização/oxigênio necessários ou espaçador inviável.`],[`Obstrução grave com resposta insuficiente a doses intermitentes, em ambiente monitorizado e com escalonamento simultâneo.`,`Obstrução grave refratária a doses intermitentes; monitorização e escalonamento simultâneo.`],[`Associar ao beta-agonista nas primeiras doses da exacerbação moderada/grave; não manter rotineiramente após a fase inicial.`,`Adjuvante ao beta-agonista na fase inicial moderada/grave; não manter rotineiramente depois.`],[`Asma grave com resposta insuficiente à terapia inalatória inicial, em ambiente monitorizado.`,`Asma grave refratária à terapia inalatória inicial; ambiente monitorizado.`],[`Crupe leve/moderado com indicação de corticosteroide ou crupe grave. Seguir a classificação de gravidade NSW/ACI.`,`Crupe leve/moderado com indicação de corticoide ou grave; classificar por NSW/ACI.`],[`Crupe moderado/grave com estridor em repouso ou deterioração, enquanto se prepara observação e via aérea de resgate.`,`Crupe moderado/grave com estridor em repouso/deterioração; preparar observação e via aérea de resgate.`],[`Hipoglicemia sintomática ou grave quando a via enteral não é segura/efetiva, seguida de identificação da causa e aporte contínuo se necessário.`,`Hipoglicemia sintomática/grave, via enteral insegura/ineficaz. Investigar causa; aporte contínuo se necessário.`],[`Selecionar a indicação e a estabilidade clínica. Cálcio estabiliza o miocárdio na hipercalemia; não reduz a concentração de potássio.`,`Selecionar indicação/estabilidade. Na hipercalemia, estabiliza miocárdio; não reduz potássio.`],[`Reversão de depressão respiratória por opioide, sem atrasar ventilação com bolsa-válvula-máscara e suporte de via aérea.`,`Depressão respiratória por opioide; não atrasar bolsa-válvula-máscara/via aérea.`],[`CAD confirmada, após iniciar fluidos e avaliar potássio; conduzir em protocolo pediátrico com correção gradual da osmolaridade.`,`CAD confirmada, após fluidos/potássio avaliados; protocolo pediátrico e correção gradual da osmolaridade.`],[`Administrar precocemente, idealmente dentro de 3 h do trauma, integrado ao protocolo de hemorragia maciça e ao controle definitivo do sangramento.`,`Idealmente até 3 h do trauma; integrar a hemorragia maciça/hemostasia definitiva.`],[`Cobertura empírica inicial em infecção bacteriana grave comunitária, ajustada a idade, foco, epidemiologia e resistência local.`,`Infecção bacteriana grave comunitária: cobertura inicial por idade, foco, epidemiologia e resistência local.`],[`Opção empírica quando há risco de Gram-negativo resistente ou Pseudomonas, guiada por foco e antibiograma institucional.`,`Cobertura empírica de Gram-negativo resistente/Pseudomonas, por foco e antibiograma institucional.`],[`Meningite bacteriana em criança >3 meses ou infecção grave com risco documentado de resistência, conforme epidemiologia e infectologia.`,`Meningite >3 meses ou infecção grave com risco documentado de resistência; epidemiologia/infectologia.`],[`Adicionar quando foco e epidemiologia sustentam MRSA ou Gram-positivo resistente; não incluir automaticamente em toda sepse.`,`Adicionar se foco/epidemiologia sugerirem MRSA/Gram-positivo resistente; não em toda sepse.`],[`No choque séptico suspeito, antimicrobiano apropriado deve começar idealmente em até 1 h do reconhecimento, após culturas quando isso não causa atraso relevante.`,`Choque séptico suspeito: antimicrobiano apropriado idealmente até 1 h do reconhecimento; culturas sem atraso relevante.`],[`Não administrar o volume calculado como se a ampola fosse 1 mg/mL: isso produz erro de 10 vezes.`,`Não usar o volume calculado com ampola 1 mg/mL: erro de 10 vezes.`],[`Para IV/IO, conferir formulação sem conservante e sem epinefrina/vasoconstritor. Não confundir lidocaína 1%, 2% e apresentações concentradas; o volume segue a apresentação selecionada.`,`IV/IO: sem conservante/epinefrina/vasoconstritor. Distinguir 1%, 2% e concentradas; volume conforme seleção.`],[`Pode ser ineficaz no coração transplantado ou bloqueio AV avançado com QRS largo; não atrasar tratamento definitivo. O teto de 0,5 mg segue AHA pediátrica, não o teto maior da bula para adolescentes. A dose mínima de 0,1 mg vale para tratamento da bradicardia; não deve ser aplicada à atropina pré-IOT.`,`Pode falhar no coração transplantado/bloqueio AV avançado com QRS largo; não atrasar tratamento definitivo. Teto AHA pediátrico 0,5 mg, não teto adolescente da bula. Mínimo 0,1 mg só na bradicardia, não pré-IOT.`],[`Contraindicada em doença broncoespástica/asma, bloqueio AV de segundo ou terceiro grau e disfunção do nó sinusal, salvo marca-passo funcionante nos bloqueios/disfunção sinusal. Não usar em taquicardia irregular ou polimórfica. Registrar ECG contínuo durante a administração.`,`Contraindicada: broncoespasmo/asma, bloqueio AV de segundo/terceiro grau ou disfunção sinusal (exceção: marca-passo funcionante nos bloqueios/disfunção sinusal). Não usar na taquicardia irregular/polimórfica. ECG contínuo.`],[`Monitorização cardiorrespiratória contínua e suporte ventilatório disponível. A bula brasileira consultada contraindica esse produto específico em recém-nascidos e crianças do sexo feminino, além de insuficiência renal/hepática/respiratória grave e porfiria; não é contraindicação universal do princípio ativo em convulsões neonatais. Identificar formulação e excipientes. Não presumir mg de sal iguais a mg de base.`,`Monitorização cardiorrespiratória contínua e suporte ventilatório. Bula deste produto: contraindicado em RN, meninas, insuficiência renal/hepática/respiratória grave e porfiria; não é contraindicação universal do fármaco na convulsão neonatal. Conferir formulação/excipientes; mg de sal ≠ mg de base.`],[`Contraindicações do produto: anúria, hemorragia intracraniana ativa (exceto durante craniotomia), desidratação grave, insuficiência cardíaca descompensada ou edema pulmonar. Não associar aditivos ou sangue na mesma linha. Pode agravar hipotensão e hipovolemia. A BTF não encontrou evidência pediátrica suficiente para recomendação de desfecho; usar como alternativa contextual.`,`Contraindicado: anúria, hemorragia intracraniana ativa (exceto craniotomia), desidratação grave, IC descompensada/edema pulmonar. Sem aditivos/sangue na mesma via. Pode agravar hipotensão/hipovolemia. BTF: evidência pediátrica de desfecho insuficiente; alternativa contextual.`],[`Ajustar na disfunção renal. Neurotoxicidade e estado de mal não convulsivo são riscos de acúmulo, especialmente na insuficiência renal.`,`Ajuste renal; acúmulo pode causar neurotoxicidade/estado de mal não convulsivo.`],[`Ajustar na disfunção renal; risco de convulsão é maior com acúmulo. Carbapenêmico não deve substituir avaliação de foco e stewardship.`,`Ajuste renal; acúmulo aumenta risco de convulsão. Avaliar foco e stewardship.`],[`Antara IV 100 mg/mL: completar a dose em SF 0,9% para concentração final 15 mg/mL e infundir em 15 min, conforme limite da bula brasileira para volume pediátrico reduzido. A carga de 60 mg/kg (máx. 4.500 mg) no estado de mal é protocolar/off-label; a bula não indica ataque para estado de mal nem uso abaixo de 6 anos. Não administrar puro; uso imediato, avaliar função renal. A concentração CHEO de 20/40 mg/mL não é transposta para este produto.`,`Antara 100 mg/mL → 15 mg/mL em SF 0,9%, 15 min (bula BR, volume pediátrico reduzido). Estado de mal: 60 mg/kg, máx. 4.500 mg, protocolar/off-label; bula não indica ataque nem uso <6 anos. Não usar puro; uso imediato; avaliar função renal. Não aplicar 20/40 mg/mL CHEO a este produto.`],[`Retirar dos frascos somente o volume necessário para a dose abaixo; não confundir volume de um frasco com volume total disponível.`,`Retirar só o volume da dose; volume por frasco ≠ total disponível.`],[`Conferir concentração do estoque, quantidade total preparada e produto antes do uso.`,`Conferir estoque, quantidade total e produto.`],[`Escolher uma alternativa, não somar doses. Administração em 5 min, dentro dos 3–5 min CHEO; não é infusão contínua.`,`Alternativas: não somar. Administrar em 5 min (CHEO: 3–5 min); não contínuo.`],[`A seleção pode ser mais estreita que a faixa da fonte. Não representa mínimo obrigatório nem teto absoluto; conferir indicação, resposta e limites específicos antes de prescrever.`,`Faixa exibida pode ser menor que a fonte; não define mínimo obrigatório ou teto absoluto. Confirmar indicação/resposta/limites.`],[`Há volume ou vazão abaixo de 0,1 mL: não aspirar/programar automaticamente; exige preparo validado e resolução adequada da seringa/bomba.`,`Volume/vazão <0,1 mL ou mL/h: confirmar preparo e resolução da seringa/bomba; não programar automaticamente.`],[`Regimes distintos; não mesclar como faixa única.`,`Regimes distintos; não mesclar.`],[`Não é máximo pediátrico atribuído à bula brasileira.`,`Máximo CHEO; não atribuído à bula BR.`],[`Apresentação utilizada neste cálculo; conferir produto, concentração, frasco/bolsa e dispositivo antes do uso.`,`Conferir produto/concentração, frasco/bolsa e dispositivo.`],[`A indicação, via e condições do ramo não são confirmadas automaticamente. Esta referência não recomenda administrar agora.`,`Referência, não ordem; confirmar indicação/via/condições.`],[`Há alternativas ou etapas distintas. A cópia conserva todas identificadas; não é prescrição conjunta e nenhuma etapa foi escolhida automaticamente.`,`Alternativas/etapas: não somar; seleção não automática.`],[`Titulação dependente da avaliação e resposta; não é autorização de iniciar ou atingir o limite.`,`Titular à resposta; limite não é alvo.`],[`Limite do contexto, não alvo obrigatório.`,`Limite do contexto; não é alvo.`],[`Volume final inclui o medicamento; não adicionar à bolsa já cheia.`,`Volume FINAL inclui o fármaco; não adicionar à bolsa cheia.`],[`A indicação clínica do paciente não foi informada ou confirmada por este cálculo.`,`Indicação individual não confirmada.`],[`CHEO separa adolescente/adulto em outro regime; a indicação do ramo deve ser conciliada pelo prescritor.`,`Adolescentes/adultos: outro regime CHEO; confirmar aplicabilidade.`],[`Concentrações padronizadas CHEO; volumes escalados por cálculo. SG 5% preserva o diluente da bula Hypofarma. Dose e estoque expressos em base, não no sal.`,`Padrões CHEO, volumes calculados; SG 5% conforme Hypofarma. Dose/estoque em base, não sal.`],[`Conferir acesso, perfusão, ECG, pressão e extravasamento. A solução de 12 mcg/mL pode exigir grande carga hídrica nos limites altos; escolher concentração/acesso conforme balanço hídrico. Não misturar com alcalinos. O preparo antigo a 40 mcg/mL permanece apenas no histórico; suas vazões não são intercambiáveis.`,`Monitorar acesso, perfusão, ECG, pressão e extravasamento. 12 mcg/mL: atenção à carga hídrica em doses altas; adequar concentração/acesso. Incompatível com alcalinos. Histórico a 40 mcg/mL: vazões não intercambiáveis.`],[`Uso pediátrico protocolar/off-label em relação à bula adulta do produto; estabilidade do preparo local não foi atribuída automaticamente.`,`Pediatria: protocolar/off-label perante a bula adulta. Estabilidade local não estabelecida.`],[`A fonte não define dose inicial separada nem máximo absoluto fora deste contexto.`,`Sem início separado ou máximo absoluto definido pela fonte.`],[`Suporte circulatório pediátrico por infusão IV; não é bolus de PCR, mini-bolus nem aplicação IM para anafilaxia.`,`Suporte circulatório pediátrico IV contínuo; não usar como bolus de PCR, mini-bolus ou IM na anafilaxia.`],[`Padrões contínuos CHEO de 6 e 25 mcg/mL; preparos volumétricos escalados por cálculo. Escolher uma solução e conferir restrição hídrica; não somar as vazões.`,`CHEO contínuo: 6 e 25 mcg/mL; volumes calculados. Escolher uma solução conforme restrição hídrica; não somar vazões.`],[`ECG, pressão, perfusão e extravasamento monitorizados. A solução antiga a 10 mcg/mL fica no histórico; nesta fonte, 10 mcg/mL aparece no mini-bolus e não valida o padrão contínuo.`,`Monitorar ECG, pressão, perfusão e extravasamento. Histórico a 10 mcg/mL: CHEO o descreve para mini-bolus, não como padrão contínuo.`],[`Não misturar com soluções alcalinas; nenhuma estabilidade local é inferida.`,`Incompatível com alcalinos; estabilidade local não estabelecida.`],[`Suporte inotrópico pediátrico por contratilidade deprimida/baixo débito; início único não definido nas linhas consultadas.`,`Inotropia pediátrica em contratilidade deprimida/baixo débito; início único não definido.`],[`Preparo de 2,5 mg/mL calculado dentro do limite farmacotécnico da bula; não é receita literal CHEO.`,`2,5 mg/mL: preparo calculado dentro do limite da bula; não é receita CHEO.`],[`CHEO limita via periférica a 5 mcg/kg/min, com cautela; acima disso o contexto requer acesso central. Acesso não informado nesta folha.`,`CHEO: periférico até 5 mcg/kg/min, com cautela; acima, central. Acesso não informado.`],[`Monitorar ECG, pressão, ritmo e perfusão. Corrigir hipovolemia conforme avaliação; preservar o alerta de lotes informado no catálogo.`,`Monitorar ECG, pressão, ritmo e perfusão; corrigir hipovolemia conforme avaliação. Conferir alerta de lotes do catálogo.`],[`Infusão IV em choque/baixo débito, individualizada. A fonte não define início único; 1 mcg/kg/min não é início preferencial nem recomendação de proteção renal.`,`Choque/baixo débito: infusão IV individualizada. Sem início único; 1 mcg/kg/min não é início preferencial nem dose de proteção renal.`],[`Concentração CHEO 3.200 mcg/mL central; receita calculada para o estoque do catálogo. Acesso central não foi informado.`,`CHEO: 3.200 mcg/mL central; preparo calculado para o estoque. Acesso central não confirmado.`],[`Analgesia pediátrica por infusão contínua; bolus de ataque é decisão separada e não é gerado automaticamente.`,`Analgesia pediátrica contínua; ataque depende de decisão separada.`],[`CHEO sustenta diluição de 5 mcg/mL em SF, embora seus padrões PICU sejam 10/50. Receita derivada por cálculo.`,`CHEO: diluição 5 mcg/mL em SF; padrões PICU 10/50. Preparo calculado.`],[`Não transpor estabilidade físico-química estrangeira para validade microbiológica do preparo local.`,`Estabilidade estrangeira não define validade microbiológica local.`],[`Não transpor prazo estrangeiro de estabilidade para validade microbiológica local.`,`Estabilidade estrangeira não define validade microbiológica local.`],[`Analgesia aguda em paciente sem tolerância prévia a opioide, área crítica e idade maior que 1 mês. Não inferir ausência de tolerância.`,`Analgesia aguda em área crítica, >1 mês; confirmar ausência de tolerância a opioide.`],[`Concentração contínua IWK 1 mg/mL; receita adaptada por cálculo ao estoque selecionado. Manter unidade nominal de sulfato, sem conversão para base.`,`IWK contínuo: 1 mg/mL; preparo calculado. Dose em sulfato, sem converter para base.`],[`Sedação pediátrica durante ventilação mecânica em ambiente monitorizado; não é o regime do estado de mal refratário. Carga, quando indicada, é decisão separada.`,`Sedação pediátrica em VM monitorizada; não usar este regime no estado de mal refratário. Carga: decisão separada.`],[`Sedação de paciente pediátrico intubado/em ventilação mecânica em cuidado intensivo, após o período neonatal.`,`Sedação pediátrica pós-neonatal, intubação/VM em UTI.`],[`A fonte não define início único de infusão; 0,2 é limite inferior e 2 é extremo deste ramo.`,`Sem início único: 0,2 é limite inferior; 2 é extremo deste ramo.`],[`Sedoanalgesia e ventilação não foram confirmadas por este cálculo. Titular ao efeito/TOF; função renal/hepática pode prolongar bloqueio. Uso em UTI pediátrica protocolar/off-label perante o produto BR do catálogo.`,`Confirmar sedoanalgesia e ventilação. Titular por efeito/TOF; disfunção renal/hepática pode prolongar bloqueio. UTI pediátrica: protocolar/off-label perante o produto BR.`],[`Suporte de baixo débito/insuficiência cardíaca refratária pediátrica; não extrapolar ao neonato/prematuro. Ataque é ramo separado.`,`Baixo débito/IC refratária pediátrica; excluir neonato/prematuro. Ataque separado.`],[`CHEO também informa máximo diário de 1,13 mg/kg/dia: conferir carga e infusão acumuladas, não informadas nesta folha.`,`CHEO: máximo 1,13 mg/kg/dia, incluindo carga e infusão; acumulado não informado.`],[`Bula Fresenius não recomenda em criança com insuficiência renal. Função renal não informada: não presumir normalidade nem importar tabela de ajuste adulta.`,`Fresenius: não recomendado na insuficiência renal pediátrica. Função renal desconhecida; não presumir normalidade nem usar ajuste adulto.`],[`Preparo 1 mg/mL em SF sustentado por CHEO; dose sustentada pelo algoritmo Colorado. A titulação exige reavaliação especializada, não escalada automática.`,`Preparo CHEO 1 mg/mL em SF; dose Colorado. Titulação especializada, sem escalada automática.`],[`Limite ponderal não dispensa alerta absoluto: acima de 25 kg, 2 mg/kg/h excede 50 mg/h. Não criar teto silencioso nem autorizar chegar ao máximo.`,`>25 kg: 2 mg/kg/h excede 50 mg/h. Máximo não é alvo; reavaliar dose absoluta.`],[`A disponibilidade desse produto não foi informada.`,`Disponibilidade não confirmada.`],[`concentração resultante aproximada`,`concentração aproximada`],[`considerando deslocamento do pó`,`incluindo deslocamento do pó`],[`da solução de origem a `,`do estoque `],[`e adicionar `,`+ `],[`Volume da dose após preparo: `,`Dose preparada: `],[`Volume de estoque para o preparo: `,`Estoque: `],[`Quantidade pela força da apresentação: `,`Quantidade: `],[`Dado necessário para completar o preparo: `,`Falta: `],[`Conferir independentemente peso, unidade, produto, concentração, via, dose, limites e programação antes da administração.`,`Dupla checagem: peso, unidade, produto, concentração, via, dose, limites e bomba.`],[`Conferir independentemente peso, unidade, produto, concentração, via, dose e programação antes da administração.`,`Dupla checagem: peso, unidade, produto, concentração, via, dose e bomba.`],[`Conferir independentemente peso, unidade, concentração, via e dose antes da administração.`,`Dupla checagem: peso, unidade, concentração, via e dose.`],[`Confirmar posição do tubo por capnografia contínua, ausculta, expansão bilateral e imagem quando disponível. Ajustar FR à idade e ao ETCO₂; confirmar PaCO₂ por gasometria. Registrar VT inspirado/expirado, Ppico, Pplatô, PEEP total, curvas e sincronia.`,`Tubo: capnografia contínua, ausculta, expansão bilateral e imagem disponível. FR por idade/ETCO₂; confirmar PaCO₂ na gasometria. Registrar VT inspirado/expirado, Ppico, Pplatô, PEEP total, curvas e sincronia.`],[`Nos primeiros minutos: SpO₂, ETCO₂ e hemodinâmica; em 15–30 min ou antes se instável: gasometria e mecânica. Corrigir primeiro circuito, tubo, secreção, pneumotórax, broncoespasmo e assincronia antes de escalar pressões.`,`Imediato: SpO₂, ETCO₂ e hemodinâmica. Em 15–30 min (antes se instável): gasometria/mecânica. Antes de elevar pressões: corrigir circuito, tubo, secreção, pneumotórax, broncoespasmo e assincronia.`],[`Titular PEEP e FiO₂ em conjunto, evitar PEEP inadequadamente baixa para a necessidade de oxigênio e medir Pplatô com pausa inspiratória quando viável. Se pressão exceder o limite, reduzir VT e reavaliar ventilação minuto, espaço morto, sincronia e necessidade de suporte avançado.`,`Titular PEEP/FiO₂ juntas; evitar PEEP insuficiente. Medir Pplatô com pausa válida. Pressão acima do limite: reduzir VT; reavaliar ventilação minuto, espaço morto, sincronia e suporte avançado.`],[`Calcular driving = Pplatô − PEEP total; complacência estática = VT expirado/(Pplatô − PEEP total). Seguir SpO₂, índice de oxigenação quando houver gasometria arterial [FiO₂ × pressão média × 100/PaO₂], balanço hídrico e tendência hemodinâmica.`,`Driving = Pplatô − PEEP total; complacência estática = VT expirado/(Pplatô − PEEP total). Monitorar SpO₂, índice de oxigenação arterial [FiO₂ × pressão média × 100/PaO₂], balanço hídrico e hemodinâmica.`],[`Reduzir ventilação minuto para permitir expiração completa; usar onda de fluxo alta, monitorar Pplatô e auto-PEEP e tratar broncoespasmo em paralelo. Priorizar mecânica e perfusão sobre normalização rápida da PaCO₂; hipercapnia permissiva exige ausência de contraindicação.`,`Reduzir ventilação minuto; permitir expiração completa. Fluxo alto, monitorar Pplatô/auto-PEEP e tratar broncoespasmo. Priorizar mecânica/perfusão; hipercapnia permissiva somente sem contraindicação.`],[`Inspecionar curva fluxo-tempo a cada ajuste, medir Pplatô e PEEP total, comparar Ppico versus Pplatô e acompanhar pressão arterial. Ppico alta com Pplatô estável sugere aumento resistivo; elevação de ambas exige avaliar hiperinsuflação/complacência.`,`A cada ajuste: curva fluxo-tempo, Pplatô, PEEP total, Ppico e PA. Ppico alta/Pplatô estável: resistência aumentada; ambas altas: avaliar hiperinsuflação/complacência.`],[`Manter normocapnia, oxigenação e perfusão; correlacionar ETCO₂ com PaCO₂ após estabilização e após mudanças relevantes. Evitar tosse, assincronia, febre, hipoxemia e hipotensão; tratar herniação como emergência tempo-dependente.`,`Manter normocapnia, oxigenação e perfusão. Correlacionar ETCO₂/PaCO₂ após estabilização e mudanças. Evitar tosse, assincronia, febre, hipoxemia e hipotensão. Herniação: emergência imediata.`],[`Reavaliar pupilas, exame neurológico possível, SpO₂, ETCO₂, pressão arterial e gasometria. Mudança abrupta do ETCO₂ pode refletir ventilação, perfusão, circuito ou tubo e não deve ser interpretada isoladamente.`,`Reavaliar pupilas, exame neurológico, SpO₂, ETCO₂, PA e gasometria. ETCO₂ abruptamente alterado: avaliar ventilação, perfusão, circuito e tubo; não interpretar isoladamente.`]];function u(e){return e?l.reduce((e,[t,n])=>e.replaceAll(t,n),e).replaceAll(`Falta: Faltam`,`Faltam`).replaceAll(`Falta: Falta`,`Falta`):``}function d(e){return[...new Set(e.map(u).map(e=>e.trim()).filter(Boolean))]}export{t as a,i,d as n,n as o,o as r,u as t};